package org.group17.starters;

import org.group17.RegistryService;

import java.io.IOException;
import java.util.Scanner;

/**
 * discovery between clients & servers
 * The registry is responsible for maintaining the status of all active servers in the network.
 * Ensuring that IDs generated by different nodes do not conflict is crucial in a distributed system.
 * The RegistryService serves as the "Single Source of Truth" responsible for distributing unique, incrementing IDs
 */
public class RegistryApp {
    public static void main(String[] args) {
        RegistryService registry = new RegistryService();
        try {
            System.out.println("Starting Registry...");
            registry.start();
            System.out.println("Registry is running on " + RegistryService.HOST + ":" + RegistryService.PORT);
            System.out.println("Press Enter to stop.");

            new Scanner(System.in).nextLine();

            registry.stop();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}